require 'db.php';
if (empty($_SESSION['admin_csrf_token'])) $_SESSION['admin_csrf_token'] = bin2hex(random_bytes(32));
$csrf = $_SESSION['admin_csrf_token'];
$page = $_GET['page'] ?? 'dashboard';
$message = '';
$allowedPages = ['dashboard','admin-account','customers','orders','reports','product-sales','order-report','add','view','edit','delete','category-add','category-view','category-edit','category-delete'];
if (!in_array($page, $allowedPages, true)) $page = 'dashboard';
function admin_h($value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function admin_redirect(string $url): never { header('Location: '.$url); exit; }
function save_product_image(mysqli $conn): ?string {
    if (empty($_FILES['image']['name'])) return null;
    if (!isset($_FILES['image']['error']) || $_FILES['image']['error'] !== UPLOAD_ERR_OK || $_FILES['image']['size'] > 5 * 1024 * 1024) throw new RuntimeException('Choose an image smaller than 5 MB.');
    $info = @getimagesize($_FILES['image']['tmp_name']);
    $mime = $info['mime'] ?? '';
    $extensions = ['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
    if (!$info || !isset($extensions[$mime])) throw new RuntimeException('Upload a JPG, PNG, or WEBP image.');
    $directory = __DIR__ . DIRECTORY_SEPARATOR . 'Ecomerse Products' . DIRECTORY_SEPARATOR . 'uploads';
    if (!is_dir($directory) && !mkdir($directory, 0755, true)) throw new RuntimeException('The upload folder is not available.');
    $filename = bin2hex(random_bytes(16)) . '.' . $extensions[$mime];
    if (!move_uploaded_file($_FILES['image']['tmp_name'], $directory . DIRECTORY_SEPARATOR . $filename)) throw new RuntimeException('The image could not be saved.');
    return 'Ecomerse Products/uploads/' . $filename;
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!is_string($_POST['admin_csrf_token'] ?? null) || !hash_equals($csrf, $_POST['admin_csrf_token'])) { http_response_code(400); exit('Your session expired. Refresh the page and try again.'); }
    $transactionOpen = false;
    try {
        if (isset($_POST['update_order_status'])) {
            $id=(int)($_POST['order_id']??0); $status=$_POST['status']??'';
            if ($id<1 || !in_array($status,['Pending','Processing','Shipped','Completed','Cancelled'],true)) throw new RuntimeException('Choose a valid order status.');
            $conn->begin_transaction();$transactionOpen=true;$check=$conn->prepare('SELECT status FROM orders WHERE id=? FOR UPDATE');$check->bind_param('i',$id);$check->execute();$existing=$check->get_result()->fetch_assoc();if(!$existing)throw new RuntimeException('Order not found.');
            if($existing['status']==='Cancelled'&&$status!=='Cancelled')throw new RuntimeException('Cancelled orders cannot be reopened.');
            if($status==='Cancelled'&&$existing['status']!=='Cancelled'){$restore=$conn->prepare('UPDATE products p JOIN order_items oi ON oi.product_id=p.id SET p.quantity=p.quantity+oi.quantity WHERE oi.order_id=?');$restore->bind_param('i',$id);$restore->execute();}
            $stmt=$conn->prepare('UPDATE orders SET status=? WHERE id=?');$stmt->bind_param('si',$status,$id);$stmt->execute();$conn->commit();$transactionOpen=false;
            admin_redirect('admin.php?page=orders&message='.urlencode('Order status updated'));
        }
        if (isset($_POST['update_admin_account'])) {
            $currentPassword=(string)($_POST['current_password']??'');
            $newUsername=trim($_POST['new_username']??'');
            $newPassword=(string)($_POST['new_password']??'');
            $confirmPassword=(string)($_POST['confirm_password']??'');
            $currentResult=$conn->query('SELECT username,password_hash FROM admin_accounts WHERE id=1');
            $currentAccount=$currentResult?$currentResult->fetch_assoc():null;
            if($currentAccount){
                $currentValid=hash_equals($currentAccount['username'],(string)($_SESSION['admin_username']??''))&&password_verify($currentPassword,$currentAccount['password_hash']);
            }else{
                $host=strtolower(preg_replace('/:\\d+$/','',(string)($_SERVER['HTTP_HOST']??'')));
                $remote=(string)($_SERVER['REMOTE_ADDR']??'');
                $local=in_array($host,['localhost','127.0.0.1','[::1]','::1'],true)&&in_array($remote,['127.0.0.1','::1'],true);
                $fallbackUsername=getenv('PHONEWIZ_ADMIN_USERNAME')?:($local?'admin':'');
                $fallbackPassword=getenv('PHONEWIZ_ADMIN_PASSWORD')?:($local?'admin123':'');
                $currentValid=$fallbackUsername!==''&&$fallbackPassword!==''&&hash_equals($fallbackUsername,(string)($_SESSION['admin_username']??''))&&hash_equals($fallbackPassword,$currentPassword);
            }
            if(!$currentValid)throw new RuntimeException('Current password is incorrect.');
            if(!preg_match('/^[A-Za-z0-9_]{3,50}$/',$newUsername))throw new RuntimeException('Username must be 3–50 characters using letters, numbers, or underscores.');
            if(strlen($newPassword)<8)throw new RuntimeException('New password must be at least 8 characters.');
            if($newPassword!==$confirmPassword)throw new RuntimeException('New password confirmation does not match.');
            $newHash=password_hash($newPassword,PASSWORD_DEFAULT);
            $save=$conn->prepare('INSERT INTO admin_accounts (id,username,password_hash) VALUES (1,?,?) ON DUPLICATE KEY UPDATE username=VALUES(username),password_hash=VALUES(password_hash)');
            $save->bind_param('ss',$newUsername,$newHash);$save->execute();
            session_regenerate_id(true);$_SESSION['admin_username']=$newUsername;
            admin_redirect('admin.php?page=admin-account&message='.urlencode('Admin account updated'));
        }
        if (isset($_POST['add_category'])) {
            $name=trim($_POST['category_name']??''); if($name===''||strlen($name)>100) throw new RuntimeException('Enter a category name up to 100 characters.');
            $stmt=$conn->prepare('INSERT INTO categories(name) VALUES(?)'); $stmt->bind_param('s',$name); $stmt->execute();
            admin_redirect('admin.php?page=category-view&message='.urlencode('Category added'));
        }
        if (isset($_POST['update_category'])) {
            $id=(int)($_POST['id']??0); $name=trim($_POST['category_name']??''); if($id<1||$name===''||strlen($name)>100) throw new RuntimeException('Enter a valid category name.');
            $stmt=$conn->prepare('SELECT name FROM categories WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$old=$stmt->get_result()->fetch_assoc();if(!$old)throw new RuntimeException('Category not found.');
            $conn->begin_transaction();$transactionOpen=true;$rename=$conn->prepare('UPDATE categories SET name=? WHERE id=?');$rename->bind_param('si',$name,$id);$rename->execute();$productsUpdate=$conn->prepare('UPDATE products SET category=? WHERE category=?');$productsUpdate->bind_param('ss',$name,$old['name']);$productsUpdate->execute();$conn->commit();$transactionOpen=false;
            admin_redirect('admin.php?page=category-view&message='.urlencode('Category updated'));
        }
        if (isset($_POST['delete_category'])) {
            $id=(int)($_POST['id']??0);$stmt=$conn->prepare('SELECT name FROM categories WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$category=$stmt->get_result()->fetch_assoc();if(!$category)throw new RuntimeException('Category not found.');
            $conn->begin_transaction();$transactionOpen=true;$clear=$conn->prepare('UPDATE products SET category="" WHERE category=?');$clear->bind_param('s',$category['name']);$clear->execute();$delete=$conn->prepare('DELETE FROM categories WHERE id=?');$delete->bind_param('i',$id);$delete->execute();$conn->commit();$transactionOpen=false;
            admin_redirect('admin.php?page=category-view&message='.urlencode('Category deleted'));
        }
        if (isset($_POST['add_product']) || isset($_POST['edit_product'])) {
            $editing=isset($_POST['edit_product']);$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$quantity=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$category=trim($_POST['category']??'');$colors=trim($_POST['colors']??'');
            if($name===''||strlen($name)>255||$price===false||$price<0||$quantity===false||$quantity<0||strlen($category)>100||strlen($colors)>255)throw new RuntimeException('Enter valid product details and non-negative price and quantity.');
            $newImage=save_product_image($conn);
            if($editing){$oldImage=trim($_POST['old_image']??'');$image=$newImage??$oldImage;$stmt=$conn->prepare('UPDATE products SET name=?,description=?,price=?,quantity=?,category=?,colors=?,image_path=? WHERE id=?');$stmt->bind_param('ssdisssi',$name,$description,$price,$quantity,$category,$colors,$image,$id);$stmt->execute();admin_redirect('admin.php?page=view&message='.urlencode('Product updated'));}
            $image=$newImage??'';$stmt=$conn->prepare('INSERT INTO products(name,description,price,quantity,category,colors,image_path) VALUES(?,?,?,?,?,?,?)');$stmt->bind_param('ssdisss',$name,$description,$price,$quantity,$category,$colors,$image);$stmt->execute();admin_redirect('admin.php?page=view&message='.urlencode('Product added'));
        }
        if (isset($_POST['delete_product'])) { $id=(int)($_POST['id']??0);$stmt=$conn->prepare('DELETE FROM products WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();admin_redirect('admin.php?page=view&message='.urlencode('Product deleted')); }
    } catch (mysqli_sql_exception $exception) {
        if ($transactionOpen) $conn->rollback();
        $message=(int)$exception->getCode()===1062?'That value already exists. Choose a different one.':'The requested change could not be saved. Check the data and try again.';
    } catch (RuntimeException $exception) {
        if ($transactionOpen) $conn->rollback();
        $message=$exception->getMessage();
    }
}

$categories=$conn->query('SELECT id,name FROM categories ORDER BY name');
$productCount=(int)$conn->query('SELECT COUNT(*) total FROM products')->fetch_assoc()['total'];
$stockCount=(int)$conn->query('SELECT COALESCE(SUM(quantity),0) total FROM products')->fetch_assoc()['total'];
$orderCount=(int)$conn->query('SELECT COUNT(*) total FROM orders')->fetch_assoc()['total'];
$customerCount=(int)$conn->query('SELECT COUNT(*) total FROM users')->fetch_assoc()['total'];
$products=$conn->query('SELECT * FROM products ORDER BY id DESC');
$orders=$page==='orders'?$conn->query('SELECT * FROM orders ORDER BY created_at DESC,id DESC'):null;
$editingProduct=null;if($page==='edit'&&isset($_GET['id'])){$id=(int)$_GET['id'];$stmt=$conn->prepare('SELECT * FROM products WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$editingProduct=$stmt->get_result()->fetch_assoc();}
$editingCategory=null;if($page==='category-edit'&&isset($_GET['id'])){$id=(int)$_GET['id'];$stmt=$conn->prepare('SELECT * FROM categories WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$editingCategory=$stmt->get_result()->fetch_assoc();}
$salesLabels=[];$salesValues=[];if($page==='dashboard'){$recent=$conn->query("SELECT DATE(created_at) day,SUM(total_amount) total FROM orders WHERE status<>'Cancelled' AND created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(created_at) ORDER BY day");while($row=$recent->fetch_assoc()){$salesLabels[]=$row['day'];$salesValues[]=(float)$row['total'];}}
