<?php if(in_array($page,['reports','product-sales','order-report'],true)){?><section class="card wide-card report-card"><div class="report-heading"><div><h2><?php echo $page==='reports'?'Sales report':($page==='product-sales'?'Product sales':'Order report');?></h2><p class="muted">Sales totals from PhoneWiz orders.</p></div><?php if($page==='reports'){?><button class="submit print-button" type="button" onclick="window.print()">Print report</button><?php }?></div><?php if($page==='reports'){?><div class="report-controls"><div class="quick-filters"><button class="filter-button active" data-filter="daily">Today</button><button class="filter-button" data-filter="weekly">This week</button><button class="filter-button" data-filter="monthly">This month</button></div><div class="range-controls"><label>From<input type="date" id="reportStart"></label><label>To<input type="date" id="reportEnd"></label><button class="submit" id="customRange">Apply dates</button></div><div class="range-controls"><label>Month<select id="reportMonth"><option value="">Month</option><?php for($m=1;$m<=12;$m++){?><option value="<?php echo $m;?>"><?php echo date('F',mktime(0,0,0,$m,1));?></option><?php }?></select></label><label>Year<select id="reportYear"><option value="">Year</option><?php for($y=(int)date('Y');$y>=2020;$y--){?><option><?php echo $y;?></option><?php }?></select></label><button class="submit" id="monthYearRange">Apply month</button></div></div><p id="reportMessage" class="notice" hidden></p><div class="report-chart-wrap"><canvas id="salesChart"></canvas></div><div class="table-box"><table id="salesTable"><thead><tr><th>Order</th><th>Customer</th><th>Product</th><th>Qty</th><th>Unit price</th><th>Subtotal</th><th>Date</th></tr></thead><tbody></tbody><tfoot><tr><th colspan="5">Grand total</th><th colspan="2" id="grandTotal">₱0.00</th></tr></tfoot></table></div><?php }elseif($page==='product-sales'){$rows=$conn->query("SELECT oi.product_name,SUM(oi.quantity) units,SUM(oi.quantity*oi.unit_price) revenue FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status<>'Cancelled' GROUP BY oi.product_name ORDER BY units DESC");?><div class="table-box"><table><tr><th>Product</th><th>Units sold</th><th>Revenue</th></tr><?php while($row=$rows->fetch_assoc()){?><tr><td><?php echo admin_h($row['product_name']);?></td><td><?php echo (int)$row['units'];?></td><td>₱<?php echo number_format((float)$row['revenue'],2);?></td></tr><?php }?></table></div><?php }else{$rows=$conn->query('SELECT id,customer_name,created_at,status,total_amount FROM orders ORDER BY created_at DESC,id DESC');?><div class="table-box"><table><tr><th>Order</th><th>Customer</th><th>Date</th><th>Status</th><th>Total</th></tr><?php while($row=$rows->fetch_assoc()){?><tr><td>#<?php echo (int)$row['id'];?></td><td><?php echo admin_h($row['customer_name']);?></td><td><?php echo admin_h($row['created_at']);?></td><td><?php echo admin_h($row['status']);?></td><td>₱<?php echo number_format((float)$row['total_amount'],2);?></td></tr><?php }?></table></div><?php }?></section><?php }?>
</main><script>document.querySelectorAll('.nav-toggle').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.menu).classList.toggle('show')));</script><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.8/dist/chart.umd.min.js"></script>
<?php if($page==='dashboard'){?><script>new Chart(document.getElementById('dashboardSalesChart'),{type:'line',data:{labels:<?php echo json_encode($salesLabels);?>,datasets:[{label:'Sales (₱)',data:<?php echo json_encode($salesValues);?>,borderColor:'#5146df',backgroundColor:'#5146df22',fill:true,tension:.3}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{beginAtZero:true}}}});</script><?php }?>
<?php if($page==='reports'){?><script src="jquery-4.0.0.min.js"></script><script>$(function(){let chart=null;const money=n=>'₱'+Number(n||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});function esc(v){return $('<div>').text(v??'').html()}function load(filter,start='',end='',month='',year=''){$.getJSON('admin-sales-data.php',{filter,start,end,month,year}).done(r=>{let html='',sum=0;(r.data||[]).forEach(o=>{(o.items||[]).forEach(i=>{html+='<tr><td>#'+o.id+'</td><td>'+esc(o.customer_name)+'</td><td>'+esc(i.product_name)+'</td><td>'+i.quantity+'</td><td>'+money(i.unit_price)+'</td><td>'+money(i.subtotal)+'</td><td>'+esc(o.created_at)+'</td></tr>'});sum+=Number(o.total)});$('#salesTable tbody').html(html||'<tr><td colspan="7">No orders found for this period.</td></tr>');$('#grandTotal').text(money(sum));const byDay={};(r.data||[]).forEach(o=>{let d=o.created_at.slice(0,10);byDay[d]=(byDay[d]||0)+Number(o.total)});if(chart)chart.destroy();chart=new Chart(document.getElementById('salesChart'),{type:'bar',data:{labels:Object.keys(byDay),datasets:[{label:'Sales (₱)',data:Object.values(byDay),backgroundColor:'#5b55df'}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{beginAtZero:true}}}})}).fail(x=>$('#reportMessage').text(x.responseJSON?.message||'Could not load the report.').prop('hidden',false))}$('.filter-button').on('click',function(){load($(this).data('filter'))});$('#customRange').on('click',()=>load('custom',$('#reportStart').val(),$('#reportEnd').val()));$('#monthYearRange').on('click',()=>load('monthyear','','',$('#reportMonth').val(),$('#reportYear').val()));load('daily')});</script><?php }?></body></html>
